  binary: item.binary,
}));

const sorted = items.map(i => i.json).sort((a, b) => a.index - b.index);
const input = sorted[0];
const sourceText = sorted.map(i => i.text).join('\n\n');
return [{ json: { title: input.title, spaceKey: input.spaceKey, template: input.template, mode: input.mode, pageUrl: input.pageUrl, instructions: input.instructions, confluenceBaseUrl: input.confluenceBaseUrl, notify: input.notify, mattermostChannelId: input.mattermostChannelId, senderEmail: input.senderEmail, parentPageId: input.parentPageId, sourceText } }];

const url = String($json.pageUrl || '').trim();
const match = url.match(/(?:\/pages\/(\d+)|[?&]pageId=(\d+))\/?(?:[?#].*)?$/i) || url.match(/^\d+$/);
const pageId = match ? (match[1] || match[2] || match[0]) : '';
if (!pageId) throw new Error('Could not determine a Confluence page ID from pageUrl');
return [{ json: { ...$json, pageId } }];

const item = items[0];
const incoming = item.json || {};
const request = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
let metadata = request.metadata || {};
if (typeof metadata === 'string' && metadata.trim()) metadata = JSON.parse(metadata);
if (!metadata || typeof metadata !== 'object') metadata = {};
let sources = metadata.sources ?? request.sources ?? incoming.sources ?? [];
if (typeof sources === 'string' && sources.trim()) sources = JSON.parse(sources);
if (!Array.isArray(sources)) sources = [];
for (const [binaryProperty, file] of Object.entries(item.binary || {})) {
  const fileName = file.fileName || binaryProperty;
  const mimeType = (file.mimeType || '').toLowerCase();
  const extension = fileName.toLowerCase().split('.').pop();
  const type = mimeType === 'application/pdf' || extension === 'pdf'
    ? 'pdfUpload'
    : mimeType === 'text/markdown' || mimeType === 'text/plain' || extension === 'md' || extension === 'markdown'
      ? 'markdownUpload'
      : null;
  if (!type) throw new Error(`Unsupported upload type: ${fileName}`);
  sources.push({ type, binaryProperty, fileName });
}
return [{ json: { ...incoming, ...metadata, sources }, binary: item.binary }];

return items.map(item => {
  const source = item.json.source || {};
  const uploaded = source.binaryProperty ? item.binary?.[source.binaryProperty] : undefined;
  if (!uploaded) return item;
  return { json: item.json, binary: { ...(item.binary || {}), data: uploaded } };
});

const allowed = new Set(['h1','h2','h3','h4','h5','h6','p','ul','ol','li','table','thead','tbody','tr','th','td','strong','em','code','pre','a','br','hr']);
const voidTags = new Set(['br','hr']);
const mark = '\u0000';
const escape = (value) => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;');
let html = typeof $json.body === 'string' ? $json.body : String($json.body || '');
html = html.replace(/^```(?:html|xhtml)?\s*/i, '').replace(/\s*```$/i, '').replace(/\*\*/g, '').replace(/__/g, '').trim();
html = html.replace(/&(?!amp;|lt;|gt;|quot;|apos;|#\d+;|#x[0-9a-f]+;)/gi, '&amp;');
html = html.replace(/<\/[a-z][a-z0-9]*(?=<\/[a-z])/gi, '');
const stack = [];
html = html.replace(/<[^>]*>/g, (token) => {
  const raw = token.slice(1, -1).trim();
  const closing = raw.startsWith('/');
  const content = (closing ? raw.slice(1) : raw).trim();
  const withoutSlash = content.endsWith('/') ? content.slice(0, -1).trim() : content;
  const name = withoutSlash.split(/\s+/)[0].toLowerCase();
  if (!/^[a-z][a-z0-9]*$/.test(name) || !allowed.has(name)) return escape(token);
  if (voidTags.has(name)) return `${mark}${name} />`;
  if (closing) {
    if (stack[stack.length - 1] === name) { stack.pop(); return `${mark}/${name}>`; }
    return '';
  }
  stack.push(name);
  return `${mark}${name}>`;
});
while (stack.length) html += `${mark}/${stack.pop()}>`;
html = html.replace(/</g, '&lt;').replace(new RegExp(mark, 'g'), '<');
if (!html.trim()) throw new Error('Generated page body is empty');
return { json: { ...$json, body: html.trim() } };

